type UIDict = Record<Lang, Record<string, string>>;

function build(raw: Record<string, string[]>): UIDict {
  const out = {} as UIDict;
  ORDER.forEach((l) => (out[l] = {}));
  for (const key of Object.keys(raw)) {
    const vals = raw[key];
    ORDER.forEach((l, i) => {
      // 容错：某个语种缺失时回退英文 → 中文 → key
      out[l][key] = vals[i] ?? vals[1] ?? vals[0] ?? key;
    });
  }
  return out;
}

export const UI: UIDict = build(RAW);

/** 取 UI 文案：当前语种优先，缺失回退英文 → 中文 → key 本身 */
export function t(lang: Lang | string, key: string): string {
  const L = (lang as Lang) in UI ? (lang as Lang) : 'en';
  const u = UI[L] || {};
  if (u[key]) return u[key];
  if (UI.en[key]) return UI.en[key];
  if (UI.zh[key]) return UI.zh[key];
  return key;
}

/** 取领域显示名（13 语）。传入 Domain（如 'film'），未知值原样返回。
 * 全站应使用本函数而非 @gph/types 的 DOMAIN_LABELS（后者仅为中文常量，用于校验/枚举）。 */
export function domainLabel(lang: Lang | string, domain: string): string {
  if (!domain) return '';
  const key = `domain.${domain}`;
  const label = t(lang, key);
  return label === key ? domain : label;
}

// 开发期断言：任一 key 的翻译数量不对齐 13 种时打印告警
if (typeof window !== 'undefined' || (typeof process !== 'undefined' && process.env?.NODE_ENV !== 'production')) {
  for (const k of Object.keys(RAW)) {
    if (RAW[k].length !== ORDER.length) {
      // eslint-disable-next-line no-console
      console.warn(`[ui] key "${k}" 有 ${RAW[k].length} 条翻译，应为 ${ORDER.length}`);
    }
  }
}
